    23	/* eslint-disable default-case, no-param-reassign */
    24	const appReducer = (state = initialState, action) =>
    25	  produce(state, draft => {
    26	    switch (action.type) {
    27	      case LOAD_REPOS:
    28	        draft.loading = true;
