    15	import { useInjectReducer } from 'utils/injectReducer';
    16	import { useInjectSaga } from 'utils/injectSaga';
    17	import {
    18	  makeSelectRepos,
    19	  makeSelectLoading,
    20	  makeSelectError,
    21	} from 'containers/App/selectors';
    22	import H2 from 'components/H2';
    23	import ReposList from 'components/ReposList';
    24	import AtPrefix from './AtPrefix';
    25	import CenteredSection from './CenteredSection';
    26	import Form from './Form';
    27	import Input from './Input';
    28	import Section from './Section';
    29	import messages from './messages';
    30	import { loadRepos } from '../App/actions';
    31	import { changeUsername } from './actions';
    32	import { makeSelectUsername } from './selectors';
    33	import reducer from './reducer';
    34	import saga from './saga';
    35	
    36	const key = 'home';
    37	
    38	export function HomePage({
    39	  username,
    40	  loading,
    41	  error,
    42	  repos,
    43	  onSubmitForm,
    44	  onChangeUsername,
    45	}) {
    46	  useInjectReducer({ key, reducer });
    47	  useInjectSaga({ key, saga });
    48	
    49	  useEffect(() => {
    50	    // When initial state username is not null, submit the form to load repos
    51	    if (username && username.trim().length > 0) onSubmitForm();
    52	  }, []);
    53	
    54	  const reposListProps = {
    55	    loading,
    56	    error,
    57	    repos,
    58	  };
    59	
    60	  return (
    61	    <article>
    62	      <Helmet>
    63	        <title>Home Page</title>
    64	        <meta
    65	          name="description"
    66	          content="A React.js Boilerplate application homepage"
    67	        />
    68	      </Helmet>
    69	      <div>
    70	        <CenteredSection>
    71	          <H2>
    72	            <FormattedMessage {...messages.startProjectHeader} />
    73	          </H2>
    74	          <p>
    75	            <FormattedMessage {...messages.startProjectMessage} />
    76	          </p>
    77	        </CenteredSection>
    78	        <Section>
    79	          <H2>
    80	            <FormattedMessage {...messages.trymeHeader} />
    81	          </H2>
    82	          <Form onSubmit={onSubmitForm}>
    83	            <label htmlFor="username">
    84	              <FormattedMessage {...messages.trymeMessage} />
    85	              <AtPrefix>
    86	                <FormattedMessage {...messages.trymeAtPrefix} />
    87	              </AtPrefix>
    88	              <Input
    89	                id="username"
    90	                type="text"
    91	                placeholder="mxstbr"
    92	                value={username}
    93	                onChange={onChangeUsername}
    94	              />
    95	            </label>
    96	          </Form>
    97	          <ReposList {...reposListProps} />
    98	        </Section>
    99	      </div>
   100	    </article>
   101	  );
   102	}
   103	
   104	HomePage.propTypes = {
   105	  loading: PropTypes.bool,
   106	  error: PropTypes.oneOfType([PropTypes.object, PropTypes.bool]),
   107	  repos: PropTypes.oneOfType([PropTypes.array, PropTypes.bool]),
   108	  onSubmitForm: PropTypes.func,
   109	  username: PropTypes.string,
   110	  onChangeUsername: PropTypes.func,
   111	};
   112	
   113	const mapStateToProps = createStructuredSelector({
   114	  repos: makeSelectRepos(),
   115	  username: makeSelectUsername(),
   116	  loading: makeSelectLoading(),
   117	  error: makeSelectError(),
   118	});
   119	
   120	export function mapDispatchToProps(dispatch) {
   121	  return {
   122	    onChangeUsername: evt => dispatch(changeUsername(evt.target.value)),
   123	    onSubmitForm: evt => {
   124	      if (evt !== undefined && evt.preventDefault) evt.preventDefault();
   125	      dispatch(loadRepos());
   126	    },
   127	  };
   128	}
   129	
   130	const withConnect = connect(
   131	  mapStateToProps,
   132	  mapDispatchToProps,
   133	);
   134	
   135	export default compose(
   136	  withConnect,
   137	  memo,
   138	)(HomePage);
===== app/containers/HomePage/saga.js
     1	/**
     2	 * Gets the repositories of the user from Github
     3	 */
     4	
     5	import { call, put, select, takeLatest } from 'redux-saga/effects';
     6	import { LOAD_REPOS } from 'containers/App/constants';
     7	import { reposLoaded, repoLoadingError } from 'containers/App/actions';
     8	
     9	import request from 'utils/request';
    10	import { makeSelectUsername } from 'containers/HomePage/selectors';
    11	
    12	/**
    13	 * Github repos request/response handler
    14	 */
    15	export function* getRepos() {
    16	  // Select username from store
    17	  const username = yield select(makeSelectUsername());
    18	  const requestURL = `https://api.github.com/users/${username}/repos?type=all&sort=updated`;
    19	
    20	  try {
    21	    // Call our request helper (see 'utils/request')
    22	    const repos = yield call(request, requestURL);
    23	    yield put(reposLoaded(repos, username));
    24	  } catch (err) {
    25	    yield put(repoLoadingError(err));
    26	  }
    27	}
    28	
    29	/**
    30	 * Root saga manages watcher lifecycle
    31	 */
    32	export default function* githubData() {
    33	  // Watches for LOAD_REPOS actions and calls getRepos when one comes in.
    34	  // By using `takeLatest` only the result of the latest API call is applied.
    35	  // It returns task descriptor (just like fork) so we can continue execution
    36	  // It will be cancelled automatically on component unmount
    37	  yield takeLatest(LOAD_REPOS, getRepos);
    38	}
