function inputs(root, files) {
  return files.map((path) => ({
    path,
    source: readFileSync(join(FIXTURE, root, path), 'utf8'),
  }));
}

// SET-A: app-rooted (mirrors webpack resolve.modules: ['node_modules', 'app'])
